import { useId } from "react";
import { Input, Segmented, Textarea } from "../../components/ui";
import type {
  ChoiceOption,
  FieldErrors,
  SpecDraft,
  SpecField,
} from "./specForm";

export interface SpecFieldsProps {
  fields: readonly SpecField[];
  draft: SpecDraft;
  /** Shown after a submit attempt. */
  errors: FieldErrors;
  onChange: (key: string, value: string) => void;
}

/**
 * Renders fields generated by `specFormFields`: text and number inputs,
 * segmented choices, line-per-item text areas, and groups as fieldsets. It
 * knows field kinds, never field names.
 */
export function SpecFields({
  fields,
  draft,
  errors,
  onChange,
}: SpecFieldsProps) {
  return (
    <>
      {fields.map((field) => (
        <FieldView
          key={field.key}
          field={field}
          draft={draft}
          errors={errors}
          onChange={onChange}
        />
      ))}
    </>
  );
}

function FieldView({
  field,
  draft,
  errors,
  onChange,
}: Omit<SpecFieldsProps, "fields"> & { field: SpecField }) {
  const value = draft[field.key] ?? "";
  const error = errors[field.key];
  switch (field.kind) {
    case "text":
      return (
        <Input
          label={field.label}
          hint={field.hint}
          error={error}
          value={value}
          placeholder={field.placeholder}
          maxLength={field.maxLength}
          required={field.required}
          autoComplete="off"
          spellCheck={false}
          onChange={(event) => onChange(field.key, event.target.value)}
        />
      );
    case "number": {
      const fallback =
        typeof field.defaultValue === "number"
          ? `${field.defaultValue} (default)`
          : "No limit";
      return (
        <Input
          type="number"
          inputMode={field.integer ? "numeric" : "decimal"}
          step={field.integer ? 1 : "any"}
          min={field.minimum ?? field.exclusiveMinimum}
          max={field.maximum ?? field.exclusiveMaximum}
          label={field.label}
          note={field.unit}
          hint={field.hint}
          error={error}
          value={value}
          placeholder={fallback}
          onChange={(event) => onChange(field.key, event.target.value)}
        />
      );
    }
    case "choice":
      return (
        <ChoiceView
          label={field.label}
          hint={field.hint}
          error={error}
          options={field.options}
          value={value}
          onChange={(next) => onChange(field.key, next)}
        />
      );
    case "variant": {
      const variant = field.variants.find((option) => option.value === value);
      return (
        <>
          <ChoiceView
            label={field.label}
            hint={field.hint}
            error={error}
            options={field.options}
            value={value}
            onChange={(next) => onChange(field.key, next)}
          />
          {variant && variant.fields.length > 0 && (
            <SpecFields
              fields={variant.fields}
              draft={draft}
              errors={errors}
              onChange={onChange}
            />
          )}
        </>
      );
    }
    case "list":
    case "map":
      return (
        <Textarea
          className="settings-field--mono"
          label={field.label}
          hint={field.hint}
          error={error}
          value={value}
          rows={3}
          spellCheck={false}
          placeholder={
            field.kind === "map"
              ? "KEY=value"
              : (field.placeholder ?? "One item per line")
          }
          onChange={(event) => onChange(field.key, event.target.value)}
        />
      );
    case "group":
      return (
        <fieldset className="settings-group">
          <legend className="ui-field__label">{field.label}</legend>
          {field.note && <p className="settings-warning">{field.note}</p>}
          {field.hint && <p className="ui-field__hint">{field.hint}</p>}
          <div className="settings-group__fields">
            <SpecFields
              fields={field.fields}
              draft={draft}
              errors={errors}
              onChange={onChange}
            />
          </div>
        </fieldset>
      );
  }
}

/**
 * A segmented choice with a visible label. A stored value the driver cannot
 * enforce stays selected (shown disabled, with a warning), so saving lets the
 * server refuse it with its own message instead of silently changing it.
 */
function ChoiceView({
  label,
  hint,
  error,
  options,
  value,
  onChange,
}: {
  label: string;
  hint?: string;
  error?: string;
  options: readonly ChoiceOption[];
  value: string;
  onChange: (value: string) => void;
}) {
  const unsupported = value !== "" && !options.some((o) => o.value === value);
  const shown = unsupported
    ? [...options, { value, label: `${value} (not supported)`, disabled: true }]
    : options;
  const id = useId();
  const hintId = `${id}-hint`;
  const unsupportedId = `${id}-unsupported`;
  const errorId = `${id}-error`;
  const describedBy =
    [hint && hintId, unsupported && unsupportedId, error && errorId]
      .filter(Boolean)
      .join(" ") || undefined;
  return (
    <div className="ui-field settings-choice">
      <div className="ui-field__head">
        <span className="ui-field__label" aria-hidden="true">
          {label}
        </span>
      </div>
      <Segmented
        variant="compact"
        label={label}
        className="settings-choice__switch"
        value={value}
        onChange={onChange}
        options={shown}
        describedBy={describedBy}
      />
      {hint && (
        <p id={hintId} className="ui-field__hint">
          {hint}
        </p>
      )}
      {unsupported && (
        <p id={unsupportedId} className="ui-field__error">
          This driver cannot enforce “{value}”. Pick another option, or the
          server will refuse the profile.
        </p>
      )}
      {error && (
        <p id={errorId} className="ui-field__error">
          {error}
        </p>
      )}
    </div>
  );
}
